const searchCopy = {
  zh: ["在线音频倒放工具 - MP3、WAV 反向播放", "音频倒放常见问题", ["能只倒放其中一段吗？", "可以。选择“选区倒放”，拖动手柄或输入开始与结束时间。生成后对比试听，下载的 WAV 只包含选中的倒放片段。"], ["手机上可以倒放音频吗？", "可以使用手机浏览器选择本地文件。推荐 MP3 或 WAV，处理时保持页面在前台。先试听结果，再从浏览器下载列表保存到设备。"], ["倒放 MP3 后仍然下载 MP3 吗？", "不是。本工具接收浏览器可解码的 MP3 等音频，输出 16 位 PCM WAV，不提供 MP3 导出。原文件不变，WAV 通常比压缩音频更大。"]],
  en: ["Audio Reverser Online - Reverse MP3 & WAV Free", "Audio reverser questions", ["Can I reverse just part of an audio file?", "Yes. Choose Selected region, drag the handles or enter start and end times, then create and compare previews. The downloaded WAV contains only that reversed clip, not the surrounding recording."], ["Can I play audio backwards on my phone?", "Choose a local file in your mobile browser. MP3 and WAV are recommended. Keep this tab in front while processing, preview the result, then save the WAV from your browser downloads."], ["Does reversing an MP3 also export MP3?", "No. This tool decodes supported audio, including MP3, and exports 16-bit PCM WAV. MP3 export is not offered. The source stays unchanged, and the WAV will usually be larger than a compressed file."]],
  ja: ["音声逆再生ツール - MP3・WAV をオンラインで反転", "音声逆再生のよくある質問", ["音声の一部だけを逆再生できますか？", "選択範囲モードでハンドルや開始・終了時刻を調整してください。試聴後に保存する WAV は、逆再生した選択範囲だけを含みます。"], ["スマートフォンでも使えますか？", "ブラウザーで端末の音声を選択できます。MP3・WAV を推奨します。処理中はページを前面に保ち、結果を試聴してダウンロードから保存してください。"], ["MP3 を逆再生すると MP3 で保存されますか？", "いいえ。対応音声をデコードし、16 ビット PCM WAV を出力します。MP3 出力はありません。元ファイルは変更せず、WAV は圧縮音声より大きくなる場合があります。"]],
  ko: ["오디오 역재생 도구 - MP3·WAV 온라인 반전", "오디오 역재생 질문", ["일부 구간만 역재생할 수 있나요?", "선택 구간 모드에서 손잡이 또는 시작·종료 시간을 조정하세요. 미리듣기를 비교한 후 저장하면 선택한 역재생 구간만 WAV로 내보냅니다."], ["휴대전화에서도 사용할 수 있나요?", "모바일 브라우저에서 기기의 오디오를 선택하세요. MP3·WAV를 권장합니다. 처리 중 페이지를 앞에 두고 결과를 들은 뒤 다운로드 목록에서 저장하세요."], ["MP3를 역재생하면 MP3로 저장되나요?", "아니요. 지원되는 오디오를 디코딩해 16비트 PCM WAV로 저장합니다. MP3 출력은 제공하지 않습니다. 원본은 그대로이며 WAV는 압축 파일보다 커질 수 있습니다."]],
  fr: ["Inverser un audio en ligne - MP3 et WAV gratuits", "Questions sur l’inversion audio", ["Puis-je inverser seulement un extrait ?", "Oui. Choisissez Zone sélectionnée et ajustez les poignées ou les temps. Après comparaison, le WAV téléchargé contient uniquement cet extrait inversé, sans le reste de l’enregistrement."], ["Puis-je lire un audio à l’envers sur téléphone ?", "Choisissez un fichier local dans votre navigateur mobile. MP3 et WAV sont conseillés. Gardez la page au premier plan, écoutez le résultat puis enregistrez le WAV depuis les téléchargements."], ["Un MP3 inversé est-il exporté en MP3 ?", "Non. Les fichiers compatibles sont décodés puis exportés en WAV PCM 16 bits. L’export MP3 n’est pas proposé. L’original reste intact et le WAV est généralement plus volumineux qu’un fichier compressé."]],
  de: ["Audio rückwärts abspielen - MP3 und WAV online", "Fragen zum Audio-Umkehren", ["Kann ich nur einen Ausschnitt umkehren?", "Ja. Auswahl wählen und Griffe oder Start- und Endzeit anpassen. Nach dem Vergleich enthält die heruntergeladene WAV nur den umgekehrten Ausschnitt, nicht den Rest der Aufnahme."], ["Kann ich Audio auf dem Telefon rückwärts abspielen?", "Wähle eine lokale Datei im mobilen Browser. MP3 und WAV werden empfohlen. Lass die Seite während der Verarbeitung im Vordergrund, höre das Ergebnis an und sichere die WAV aus der Download-Liste."], ["Wird ein umgekehrtes MP3 auch als MP3 gespeichert?", "Nein. Unterstütztes Audio wird dekodiert und als 16-Bit-PCM-WAV exportiert. MP3-Ausgabe ist nicht verfügbar. Die Quelle bleibt unverändert; WAV ist meist größer als eine komprimierte Datei."]],
  es: ["Invertir audio online gratis - MP3 y WAV al revés", "Preguntas sobre invertir audio", ["¿Puedo invertir solo una parte del audio?", "Sí. Elige Región seleccionada y ajusta los controles o los tiempos. Después de comparar las escuchas, el WAV descargado contiene solo el fragmento invertido, sin el resto de la grabación."], ["¿Puedo escuchar audio al revés en el móvil?", "Elige un archivo local en el navegador móvil. Recomendamos MP3 y WAV. Mantén la página en primer plano, escucha el resultado y guarda el WAV desde las descargas del navegador."], ["¿Un MP3 invertido también se guarda en MP3?", "No. El audio compatible se decodifica y exporta como WAV PCM de 16 bits. No hay salida MP3. El original no cambia y el WAV suele ocupar más que un archivo comprimido."]]
};
const data = Object.fromEntries(Object.entries(rows).map(([locale, values]) => {
  if (values.length !== keys.length) throw new Error(`Reverser translation mismatch: ${locale} ${values.length}/${keys.length}`);
  const labels = Object.fromEntries(keys.map((key, i) => [key, values[i]]));
  const [seoTitle, faqTitle, ...faqs] = searchCopy[locale];
  return [locale, { title: labels.title, seoTitle, faqTitle, faqs, description: labels.description, intro: labels.intro, labels,
    sections: [[labels.qualityTitle, labels.quality], [labels.phoneTitle, labels.phone]] }];
}));
module.exports = { data };
